 async function message(number,value){assert(typeof input.onmidimessage==='function','Controlled input disconnected');const bytes=[0xb0,number,value],timestamp=performance.now();result.events.push({bytes,deviceId:input.id,timestamp});input.onmidimessage({data:Uint8Array.from(bytes),timeStamp:timestamp});await sleep(50);}
