 async function frame(label){await sleep(90);const canvas=$('#video-master');assert(canvas,'Missing real Video output');const rgba=canvas.getContext('2d').getImageData(0,0,canvas.width,canvas.height).data,dataURL=canvas.toDataURL('image/png'),bytes=Uint8Array.from(atob(dataURL.split(',')[1]),x=>x.charCodeAt(0));const analysis=engine.videoAnalysis?.(0)||{};const record={label,width:canvas.width,height:canvas.height,timestamp:performance.now(),contextTime:engine.ctx.currentTime,bass:analysis.bass,audioAvailable:analysis.audioAvailable,red:bounds(rgba,canvas.width,canvas.height,'red'),green:bounds(rgba,canvas.width,canvas.height,'green'),blue:bounds(rgba,canvas.width,canvas.height,'blue'),sha256:await sha(bytes),dataURL};result.frames.push(record);const{dataURL:_,...summary}=record;return summary;}
 async function fixture(kind,second=false){const canvas=document.createElement('canvas');canvas.width=48;canvas.height=32;const context=canvas.getContext('2d');context.fillStyle=second?'#0000ff':'#ff0000';context.fillRect(0,0,48,32);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png')),bytes=new Uint8Array(await blob.arrayBuffer());const record={name:kind+(second?'-B':'-A')+'.png',width:48,height:32,sha256:await sha(bytes),base64:btoa(String.fromCharCode(...bytes))};result.fixtures.push(record);return record;}
 async function importImage(record){const bytes=Uint8Array.from(atob(record.base64),x=>x.charCodeAt(0)),transfer=new DataTransfer();transfer.items.add(new File([bytes],record.name,{type:'image/png'}));const node=$('#video-overlay-image');node.files=transfer.files;node.dispatchEvent(new Event('change',{bubbles:true}));await until(()=>!node.disabled&&$('#video-overlay-asset')?.textContent.includes('decoded'),'Actual owned image decode');}
 async function assign(kind,action,number){const selector=selectorFor(action),control=$(selector);assert(control?.dataset.videoMidiTarget==='Video '+kind+' overlay '+action,'Visible target annotation mismatch '+action);click('#modal-body [data-video-midi-mode]');assert(document.body.classList.contains('video-midi-assigning'),'Assignment not active');click(selector);const before=state.mappings.length;await message(number,127);assert(state.mappings.length===before+1,'Input did not learn '+action);assert(state.mappings.at(-1).target==='Video '+kind+' overlay '+action,'Wrong learned target');click('#modal-body [data-video-midi-mode]');assert(!document.body.classList.contains('video-midi-assigning'),'Explicit Exit failed');}
