  result.sourceBefore=await hashes();await engine.resume();engine.audioMonitor.mutePhysical(true);await until(()=>engine.audioMonitor.snapshot().physicalMuted,'Observed physical-output mute',2000);result.physicalMuted=true;result.audioBefore=audio();
  mapper();click('#midi-connect');await until(()=>typeof input.onmidimessage==='function','Controlled MIDI connection');
